sp_widget.css:
.directory-hero{

background:
linear-gradient(
135deg,
#071733,
#1D46D5
);

min-height:340px;

padding:56px;

border-radius:
0 0 36px 36px;

display:flex;

justify-content:
space-between;

align-items:center;

gap:40px;

color:white;

overflow:hidden;

}



/* LEFT */

.hero-left{

max-width:620px;

}



/* BADGE */

.hero-badge{

display:inline-block;

padding:
10px 18px;

border-radius:
999px;

background:
rgba(
255,
255,
255,
.12
);

font-weight:
700;

letter-spacing:
1.5px;

font-size:
10px;

}



/* TITLE */

.hero-left h1{

font-size:
56px;

margin:
22px 0;

font-weight:
900;

line-height:
1.05;

}



/* DESCRIPTION */

.hero-left p{

font-size:
18px;

line-height:
1.7;

opacity:
.90;

max-width:
520px;

}



/* ACTIONS */

.hero-actions{

display:flex;

gap:14px;

flex-wrap:wrap;

margin-top:26px;

}



/* BACK */

.back-btn{

display:inline-flex;

align-items:center;

justify-content:center;

padding:
0 28px;

height:50px;

border-radius:
16px;

background:
rgba(
255,
255,
255,
.12
);

color:white;

font-size:
13px;

font-weight:
800;

text-decoration:none;

backdrop-filter:
blur(20px);

transition:.25s;

}


.back-btn:hover{

transform:
translateY(-2px);

}



/* MAIN BUTTON */

.hero-btn{

display:inline-flex;

align-items:center;

justify-content:center;

height:50px;

padding:
0 28px;

border-radius:
16px;

background:
linear-gradient(
90deg,
#17D698,
#35D6AE
);

color:
white;

font-size:
13px;

font-weight:
800;

text-decoration:
none;

transition:.25s;

}


.hero-btn:hover{

transform:
translateY(-2px);

}



/* RIGHT CARD */

.hero-card{

width:
190px;

height:
190px;

border-radius:
28px;

background:
rgba(
255,
255,
255,
.12
);

backdrop-filter:
blur(
20px
);

display:flex;

flex-direction:
column;

justify-content:
center;

align-items:
center;

}



.hero-number{

font-size:
54px;

font-weight:
900;

}



.hero-label{

font-size:
15px;

margin-top:
6px;

}



/* TABLET */

@media(max-width:900px){

.directory-hero{

padding:44px 34px;

flex-direction:column;

text-align:center;

min-height:auto;

}

.hero-left{

max-width:100%;

}

.hero-left h1{

font-size:42px;

}

.hero-left p{

font-size:15px;

margin:auto;

}

.hero-actions{

justify-content:center;

}

.hero-card{

width:180px;

height:180px;

}

}



/* MOBILE */

@media(max-width:600px){

.directory-hero{

padding:34px 20px;

gap:30px;

}

.hero-left h1{

font-size:34px;

}

.hero-left p{

font-size:13px;

}

.hero-card{

width:150px;

height:150px;

}

.hero-number{

font-size:42px;

}

.hero-label{

font-size:13px;

}

.back-btn,
.hero-btn{

width:100%;

}

}

sp_widget.script:
(function(){

data.total=0;

var gr=
new GlideAggregate(
'x_1902481_employ_0_employee'
);

gr.addAggregate(
'COUNT'
);

gr.query();

if(
gr.next()
){

data.total=
gr.getAggregate(
'COUNT'
);

}

})();
